import * as t from "tap";
import { mergeApiAuthTypes as merge } from "./mergeApiAuthTypes";

t.test("it works", async (t) => {
  t.same(
    merge(
      [
        {
          type: "http",
          scheme: "bearer",
        },
        {
          type: "apiKey",
          in: "header",
          name: "x-api-key",
        },
      ],
      [
        {
          type: "http",
          scheme: "bearer",
        },
        {
          type: "http",
          scheme: "basic",
        },
        {
          type: "apiKey",
          in: "header",
          name: "x-api-key-v2",
        },
      ]
    ),
    [
      {
        type: "http",
        scheme: "bearer",
      },
      {
        type: "apiKey",
        in: "header",
        name: "x-api-key",
      },
      {
        type: "http",
        scheme: "basic",
      },
      {
        type: "apiKey",
        in: "header",
        name: "x-api-key-v2",
      },
    ]
  );

  t.same(merge(undefined, undefined), undefined);

  t.same(
    merge(
      [
        {
          type: "http",
          scheme: "bearer",
        },
      ],
      undefined
    ),
    [
      {
        type: "http",
        scheme: "bearer",
      },
    ]
  );

  t.same(
    merge(undefined, [
      {
        type: "http",
        scheme: "digest",
      },
    ]),
    [
      {
        type: "http",
        scheme: "digest",
      },
    ]
  );
});

import * as t from "tap";
import { getApiAuthType as get } from "./getApiAuthType";
import type { Context } from "../Context";

function getContext(
  headers: Record<string, string> = {},
  cookies: Record<string, string> = {}
): Context {
  return {
    method: "GET",
    route: "/test",
    headers,
    body: undefined,
    remoteAddress: "",
    url: `http://localhost/test`,
    routeParams: {},
    query: {},
    cookies,
    source: "test",
  };
}

t.test("it detects authorization header", async (t) => {
  t.same(get(getContext({ authorization: "Bearer token" })), [
    { type: "http", scheme: "bearer" },
  ]);
  t.same(get(getContext({ authorization: "Basic base64" })), [
    { type: "http", scheme: "basic" },
  ]);
  t.same(get(getContext({ authorization: "custom" })), [
    { type: "apiKey", in: "header", name: "Authorization" },
  ]);
});

t.test("it detects api keys", async (t) => {
  t.same(get(getContext({ "x-api-key": "token" })), [
    { type: "apiKey", in: "header", name: "x-api-key" },
  ]);
  t.same(get(getContext({ "api-key": "token" })), [
    { type: "apiKey", in: "header", name: "api-key" },
  ]);
});

t.test("it detects auth cookies", async (t) => {
  t.same(get(getContext({}, { "api-key": "token" })), [
    { type: "apiKey", in: "cookie", name: "api-key" },
  ]);
  t.same(get(getContext({}, { session: "test" })), [
    {
      type: "apiKey",
      in: "cookie",
      name: "session",
    },
  ]);
});

t.test("no auth", async (t) => {
  t.same(get(getContext()), undefined);
  t.same(get(getContext({})), undefined);
  t.same(get(getContext({ authorization: "" })), undefined);
  // @ts-expect-error Testing edge case
  t.same(get({}), undefined);
});

const t = require("tap");
const { spawn } = require("child_process");
const { resolve } = require("path");
const timeout = require("../timeout");

const pathToApp = resolve(
  __dirname,
  "../../sample-apps/hapi-postgres",
  "app.js"
);

t.test("it blocks in blocking mode", (t) => {
  const server = spawn(`node`, [pathToApp, "4000"], {
    env: { ...process.env, AIKIDO_DEBUG: "true", AIKIDO_BLOCKING: "true" },
  });

  server.on("close", () => {
    t.end();
  });

  server.on("error", (err) => {
    t.fail(err.message);
  });

  let stdout = "";
  server.stdout.on("data", (data) => {
    stdout += data.toString();
  });

  let stderr = "";
  server.stderr.on("data", (data) => {
    stderr += data.toString();
  });

  // Wait for the server to start
  timeout(2000)
    .then(() => {
      return Promise.all([
        fetch(
          `http://127.0.0.1:4000/?petname=${encodeURIComponent("Njuska'); DELETE FROM cats;-- H")}`,
          {
            signal: AbortSignal.timeout(5000),
          }
        ),
        fetch("http://127.0.0.1:4000/?petname=Njuska", {
          signal: AbortSignal.timeout(5000),
        }),
      ]);
    })
    .then(async ([noSQLInjection, normalSearch]) => {
      t.equal(noSQLInjection.status, 500);
      t.equal(normalSearch.status, 200);
      t.match(stdout, /Starting agent/);
      t.match(await noSQLInjection.text(), /Zen has blocked an SQL injection/);
    })
    .catch((error) => {
      t.fail(error.message);
    })
    .finally(() => {
      server.kill();
    });
});

t.test("it does not block in dry mode", (t) => {
  const server = spawn(`node`, [pathToApp, "4001"], {
    env: { ...process.env, AIKIDO_DEBUG: "true" },
  });

  server.on("close", () => {
    t.end();
  });

  let stdout = "";
  server.stdout.on("data", (data) => {
    stdout += data.toString();
  });

  let stderr = "";
  server.stderr.on("data", (data) => {
    stderr += data.toString();
  });

  // Wait for the server to start
  timeout(2000)
    .then(() =>
      Promise.all([
        fetch(
          `http://127.0.0.1:4001/?petname=${encodeURIComponent("Njuska'); DELETE FROM cats;-- H")}`,
          {
            signal: AbortSignal.timeout(5000),
          }
        ),
        fetch("http://127.0.0.1:4001/?petname=Njuska", {
          signal: AbortSignal.timeout(5000),
        }),
      ])
    )
    .then(async ([noSQLInjection, normalSearch]) => {
      t.equal(noSQLInjection.status, 200);
      t.equal(normalSearch.status, 200);
      t.match(stdout, /Starting agent/);
      t.notMatch(
        await noSQLInjection.text(),
        /Zen has blocked an SQL injection/
      );
    })
    .catch((error) => {
      t.fail(error.message);
    })
    .finally(() => {
      server.kill();
    });
});

