t.test("it stops sending requests if rate limited", async (t) => {
  const clock = FakeTimers.install();

  const api = new ReportingAPIForTesting();
  const rateLimitedAPI = new ReportingAPIRateLimitedServerSide(api);
  const token = new Token("token");

  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: true,
    endpoints: [],
    heartbeatIntervalInMS: 10 * 60 * 1000,
    configUpdatedAt: 0,
    blockedUserIds: [],
    allowedIPAddresses: [],
    blockNewOutgoingRequests: false,
    domains: [],
    excludedUserIdsFromRateLimiting: [],
  });
  t.match(api.getEvents(), [{ type: "started" }]);

  api.setResult({ success: false, error: "timeout" });
  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "timeout",
  });
  t.match(api.getEvents(), [{ type: "started" }, { type: "started" }]);

  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "timeout",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  api.setResult({ success: false, error: "rate_limited" });
  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "rate_limited",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "rate_limited",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  clock.tick(30 * 60 * 1000);
  api.setResult({
    success: true,
    endpoints: [],
    heartbeatIntervalInMS: 10 * 60 * 1000,
    configUpdatedAt: 0,
    blockedUserIds: [],
    allowedIPAddresses: [],
    excludedUserIdsFromRateLimiting: [],
  });
  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: true,
    endpoints: [],
    heartbeatIntervalInMS: 10 * 60 * 1000,
    configUpdatedAt: 0,
    blockedUserIds: [],
    allowedIPAddresses: [],
    excludedUserIdsFromRateLimiting: [],
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  api.setResult({ success: false, error: "rate_limited" });
  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "rate_limited",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "rate_limited",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  clock.uninstall();
});

import * as t from "tap";
import isEmail from "./isEmail";

t.test("is a valid email", async (t) => {
  t.same(isEmail("hello@example.com"), true);
  t.same(isEmail("hello@aikido.dev"), true);
  t.same(isEmail("info@abcö.de"), true);
  t.same(isEmail("hello+test@aikido.dev"), true);
  t.same(isEmail("ö@example.com"), true);
  t.same(isEmail('"ö"@ö.de'), true);
});

t.test("is not a valid email", async (t) => {
  t.same(isEmail(""), false);
  t.same(isEmail("example"), false);
  t.same(isEmail("@"), false);
  t.same(isEmail("@.com"), false);
  t.same(isEmail("@example.com"), false);
  t.same(isEmail(".@example.com"), false);
  t.same(isEmail("hello@.com"), false);
  t.same(isEmail("hello@com"), false);
  t.same(isEmail("hello@com."), false);
  t.same(isEmail("hello@.com."), false);
  t.same(isEmail("hello@.com"), false);
  t.same(isEmail("hello@com."), false);
  t.same(isEmail("hello@com.."), false);
  t.same(isEmail("hello@example.com."), false);
  t.same(isEmail("hello@.example.com"), false);
  t.same(isEmail("hell o@example.com"), false);
  t.same(isEmail("abcde".repeat(64) + "@example.com"), false);
});

